/** user-defined types **/

export type AdminStatus = { isAdmin: boolean; canElevate: boolean }
export type AllScores = { dataProtection: number; services: number; hardening: number; performance: number; bloatware: number | null }
export type AppDiagnostics = { checks: DiagnosticCheck[]; hasCriticalFailure: boolean }
export type AvailableItem = { id: string; label: string; category: string }
export type AvailableItems = { dataProtection: AvailableItem[]; hardening: AvailableItem[]; performance: AvailableItem[]; services: AvailableItem[]; bloatware: AvailableItem[]; startup: AvailableItem[] }
export type BatchOptions = { dryRun?: boolean }
export type BatchResult = { total: number; success: number; failed: number; errors: string[]; dryRun: boolean; previewItems: string[] }
export type BenchmarkEntry = { timestamp: string; result: BenchmarkResult; 
/**
 * Recalcule a chaque lecture : faux pour une entree dont un score sort des bornes
 * plausibles (anciennes versions du banc), sans reecrire le fichier de l'utilisateur.
 */
plausible?: boolean; 
/**
 * Lignee du banc qui a mesure (`LIGNEE_BANC`), jamais la version affichee. Absente des
 * entrees ecrites avant 2.18.0, dont la metrique CPU n'est pas comparable a celle d'aujourd'hui.
 */
version?: string | null }
export type BenchmarkResult = { cpuScore: number; memoryScore: number; diskReadScore: number; diskWriteScore: number; networkLatency: number; overallScore: number; durationMs: number }
export type BloatwareItem = { packageName: string; displayName: string; publisher: string; category: string; isInstalled: boolean; version: string }
export type ChangeRequest = { keyPath: string; valueName: string; changeType: ChangeRequestType; 
/**
 * Requis pour RestoreModified et RestoreRemoved (raw .reg : "dword:00000001" ou "\"hello\"").
 * Ignoré pour UndoAdded.
 */
targetValue: string | null }
export type ChangeRequestType = 
/**
 * Valeur diffère entre snapshot et live → restaurer celle du snapshot
 */
{ type: "restoreModified" } | 
/**
 * Valeur absente en live mais présente en snapshot → recréer
 */
{ type: "restoreRemoved" } | 
/**
 * Valeur présente en live mais absente en snapshot → supprimer
 */
{ type: "undoAdded" }
export type CleanResult = { freedBytes: number; errors: string[]; dryRun: boolean; previewItems: string[] }
export type CleanupTarget = { id: string; name: string; description: string; path: string; sizeBytes: number; sizeDisplay: string; isSystem: boolean; accessible: boolean }
/**
 * Enum semantique pour les erreurs de commandes Tauri.
 * 
 * Permet au frontend de presenter des messages coherents et actionnables
 * au lieu de strings opaques. Chaque variant sera serialise sous la forme
 * `{ "code": "NotAdmin", "details": "..." }` pour une discrimination facile
 * cote TypeScript.
 * 
 * # Migration progressive
 * 
 * Les commandes existantes continuent a fonctionner avec `Result<T, String>`.
 * Les nouvelles commandes devraient utiliser `Result<T, CommandError>` pour
 * beneficier de la discrimination cote frontend. `CommandError` implemente
 * `From<String>` et `From<&str>` pour faciliter l'adoption progressive.
 */
